#!/usr/bin/env python3
# Frozen RC1 fresh fixture payload. Created after target/control freeze and before decisive execution.
import base64,zlib,json,hashlib
from pathlib import Path
PAYLOAD=''
EXPECTED={'fresh_cases.jsonl':'42068ca5373d9c808cff9de02bb6a2759e35803d732838f9572a588b222465e4','GOLD/fresh_gold.jsonl':'8f619fef47c1b5dd48744a073f267d80db63811e0e056583b82c33722ac32693'}
def materialize(root:Path)->None:
    obj=json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    for rel,text in obj.items():
        p=root/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8',newline='\n')
        got=hashlib.sha256(text.encode()).hexdigest()
        if got!=EXPECTED[rel]: raise SystemExit(f'hash mismatch {rel} {got}')
if __name__=='__main__': materialize(Path(__file__).resolve().parent)
